+ */
+public class DenseVectorMappingUpdateIT extends AbstractRollingUpgradeTestCase {
+
+    private static final String BULK1 = """
+                    {"index": {"_id": "1"}}
+                    {"embedding": [1, 1, 1, 1]}
+                    {"index": {"_id": "2"}}
+                    {"embedding": [1, 1, 1, 2]}
+                    {"index": {"_id": "3"}}
+                    {"embedding": [1, 1, 1, 3]}
