+public final class CombineEvals extends OptimizerRules.OptimizerRule<Eval> {
+
+    public CombineEvals() {
+        super(OptimizerRules.TransformDirection.UP);
+    }
+
+    @Override
+    protected LogicalPlan rule(Eval eval) {
