+
+    @Override
+    protected LogicalPlan rule(Aggregate agg) {
+        OrderBy order = findPullableOrderBy(agg.child());
+
+        LogicalPlan p = agg;
+        if (order != null) {
+            p = agg.transformDown(OrderBy.class, o -> o == order ? order.child() : o);
+        }
+        return p;
